input.command:
node --input-type=module - <<'EOF'
import {readFileSync} from 'node:fs';
const read = p => JSON.parse(readFileSync(p,'utf8'));
const plan = read('shift-plan.json');
const rel = read('release.json');
const rev = read('operations/revision-receipt.json');
const orig = read('operations/original-receipt.json');
const night = read('night.json');
const req = night.buses.map(b=>b.requiredKwh);
const margins = rel.departureKwh.map((v,i)=>v-req[i]);
const at90 = Object.fromEntries(['A','B'].map((id,i)=>[id, margins[i]>=0?'GO':'HOLD']));
const checks = {
  planMatchesReceipt: JSON.stringify(plan.acKw)===JSON.stringify(rev.requested),
  planWithinLimits: plan.acKw.every((v,i)=>v<=rev.limits[i]),
  departureMatchesReceipt: JSON.stringify(rel.departureKwh)===JSON.stringify(rev.departureKwh),
  marginsCorrect: JSON.stringify(rel.marginKwh)===JSON.stringify(margins),
  at90Correct: JSON.stringify(rel.at90)===JSON.stringify(at90),
  at85BothHold: rel.at85.A==='HOLD' && rel.at85.B==='HOLD',
  evidenceMatchesReceiptSha: rel.evidenceSha===rev.sha,
  revisionWithinLimits: rev.withinLimits===true,
  originalPreserved: orig.sha==='341e19e288de9f561f85fcb66a7a910ff6f3e143' && JSON.stringify(orig.actual)==='[80,40,50,50]',
  minShiftRetained: plan.loadShiftKw===night.shiftFromSlot*0+20,
  dispatchAt85False: plan.dispatchAt85===false,
};
console.log(JSON.stringify({required:req,margins,at90,checks},null,2));
if (Object.values(checks).some(v=>!v)) process.exit(1);
EOF
